/**
 * Every photo considered for the site, classified by eye (see docs/PHOTO_MAP.md).
 * `file` is relative to the project root. Folder photos (photos/) always win over online ones.
 * Processed outputs are generated by `pnpm assets:photos` into public/images/<id>-<width>.<ext>.
 * Plain data only: this file is imported by both the app and the Node asset scripts.
 */

export type PhotoKind =
  | "dish"
  | "drink"
  | "interior"
  | "exterior"
  | "chef-team"
  | "table-ambiance"
  | "detail-texture"
  | "menu-board"
  | "unusable";

export type PhotoUsage = "hero-poster" | "intro" | "chef" | "signature" | "menu" | "gallery" | "og";

export type Confidence = "high" | "medium" | "low";

export type PhotoEntry = {
  id: string;
  file: string;
  source: "folder" | "online";
  /** Original URL for online photos (also listed in docs/PHOTO_SOURCES.md). */
  sourceUrl?: string;
  kind: PhotoKind;
  itemIds: string[];
  confidence: Confidence;
  /** 0–1, used for object-position and for focal crops (og, thumbnails). */
  focalPoint: { x: number; y: number };
  notes: string;
  usage: PhotoUsage[];
  alt: { fr: string; en: string; ar?: string };
  /** Process into public/images. Unused duplicates stay documented but are skipped. */
  process: boolean;
};

const F = "photos/SnapInsta.to_";

