export function photoById(id: string): PhotoEntry | undefined {
  return photoMap.find((p) => p.id === id);
}

export function photosForItem(itemId: string): PhotoEntry[] {
  return photoMap.filter((p) => p.process && p.usage.includes("menu") && p.itemIds[0] === itemId);
}
